import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());

        Mint[][] p = new Mint[N][N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                p[i][j] = new Mint(Integer.parseInt(st.nextToken())) / new Mint(100);
            }
        }

        Map<BitSet, Mint> currentMap = new HashMap<>();
        Map<BitSet, Mint> nextMap = new HashMap<>();

        BitSet b = new BitSet(N);
        b.set(0);
        currentMap.put(b, new Mint(1));

        for (int i = 0; i < N; i++) {
            for (Map.Entry<BitSet, Mint> entry : currentMap.entrySet()) {
                BitSet bitset = (BitSet) entry.getKey().clone();
                Mint prob = entry.getValue();

                List<Integer> ones = new ArrayList<>();
                for (int idx = 0; idx < (1 << N); idx++) {
                    if (bitset.get(idx)) {
                        ones.add(idx);
                    }
                }

                for (int e = 0; e < (1 << N); e++) {
                    Mint pr = new Mint(1);
                    for (int j = 0; j < N; j++) {
                        if (((e >> j) & 1) == 1) {
                            pr = pr.times(p[i][j]);
                        } else {
                            pr = pr.minus(Mint.ONE).times(p[i][j]);
                        }
                    }

                    BitSet nb = new BitSet(N);
                    for (int xIdx : ones) {
                        for (int r = 0; r < N; r++) {
                            if (((e >> r) & 1) == 1 && !bitset.get(r)) {
                                BitSet newBitSet = (BitSet) bitset.clone();
                                newBitSet.set(r);
                                nb = (BitSet) newBitSet.clone();
                            }
                        }
                    }

                    // Update nextMap
                    Mint existing = nextMap.getOrDefault(nb, new Mint(0));
                    nextMap.put(nb, existing.plus(prob.times(pr)));
                }
            }
            currentMap = new HashMap<>(nextMap);
            nextMap.clear();
        }

        Mint answer = new Mint(0);
        for (Map.Entry<BitSet, Mint> entry : currentMap.entrySet()) {
            BitSet key = entry.getKey();
            if (key.get((1 << N) - 1)) {
                answer = answer.plus(entry.getValue());
            }
        }

        pw.println(answer);
        pw.flush();
    }

    static class Mint {
        static final Mint ONE = new Mint(1);
        long v;
        static final long MOD = 1000000007;

        Mint(long v) {
            this.v = ((v % MOD) + MOD) % MOD;
        }

        Mint plus(Mint other) {
            return new Mint(this.v + other.v);
        }

        Mint minus(Mint other) {
            return new Mint(this.v - other.v);
        }

        Mint times(Mint other) {
            return new Mint(this.v * other.v % MOD);
        }

        Mint div(Mint other) {
            return this.times(other.inv());
        }

        Mint inv() {
            return new Mint(modInverse(this.v, MOD));
        }

        private static long modInverse(long a, long m) {
            long m0 = m, t, q;
            long x0 = 0, x1 = 1;

            if (m == 1)
                return 0;

            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m;
                a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }

            if (x1 < 0)
                x1 += m0;

            return x1;
        }

        @Override
        public String toString() {
            return String.valueOf(v);
        }
    }
